38	export interface CertificateDetectionConfig {
39	  enableTelemetry: boolean;
40	  scanTimeoutMs: number;
41	  excludedExtensions: string[];
42	  validCertExtensions: string[];
43	  certDirectories: { system: string[]; user: string[] };
44	  followSymlinks: boolean;
45	}
