59	export class CertificateDetectionService {
60	  private config: CertificateDetectionConfig;
61	  private readonly telemetryLogger?: extensionApi.TelemetryLogger;
62	
63	  constructor(telemetryLogger?: extensionApi.TelemetryLogger, config?: Partial<CertificateDetectionConfig>) {
64	    this.telemetryLogger = telemetryLogger;
65	    this.config = { ...DEFAULT_CONFIG, ...config };
66	  }
67	
68	  async detectCustomCertificates(): Promise<CertificateDetectionResult> {
69	    if (this.config.enableTelemetry && this.telemetryLogger) {
70	      const startTime = Date.now();
71	
72	      try {
73	        const result = await this.performDetection();
74	        result.scanDurationMs = Date.now() - startTime;
75	
76	        await this.sendTelemetry(result);
77	
78	        return result;
79	      } catch (error) {
80	        const fallbackResult: CertificateDetectionResult = {
81	          hasCustomCertificates: false,
82	          certificateCount: 0,
83	          scanDurationMs: Date.now() - startTime,
84	          errors: [{ error: String(error) }],
85	        };
86	
87	        await this.sendTelemetry(fallbackResult);
88	
89	        return fallbackResult;
90	      }
91	    }
92	
93	    // return minimal result without scanning
94	    return {
95	      hasCustomCertificates: false,
96	      certificateCount: 0,
97	      scanDurationMs: 0,
98	      errors: [],
99	    };
100	  }
101	
102	  private async performDetection(): Promise<CertificateDetectionResult> {
103	    const result: CertificateDetectionResult = {
104	      hasCustomCertificates: false,
105	      certificateCount: 0,
106	      scanDurationMs: 0,
107	      errors: [],
108	    };
109	
110	    const directories = await this.getDirectoriesToScan();
111	    const scanPromise = this.scanDirectories(directories, result);
112	    const timeoutPromise = new Promise<void>((_, reject) =>
113	      setTimeout(() => reject(new Error('Scan timeout')), this.config.scanTimeoutMs),
114	    );
115	
116	    try {
117	      await Promise.race([scanPromise, timeoutPromise]);
118	    } catch (error) {
119	      if (error instanceof Error && error.message === 'Scan timeout') {
120	        result.errors.push({ error: 'Scan operation timed out' });
121	      } else {
122	        throw error;
123	      }
124	    }
125	
126	    result.hasCustomCertificates = result.certificateCount > 0;
127	    return result;
128	  }
129	
130	  private async scanDirectories(directories: string[], result: CertificateDetectionResult): Promise<void> {
131	    const scanTasks = directories.map(dir => this.scanDirectory(dir, result, 0));
132	
133	    await Promise.allSettled(scanTasks);
134	  }
135	
136	  private async scanDirectory(dirPath: string, result: CertificateDetectionResult, depth: number): Promise<void> {
137	    try {
138	      const entries = await fs.readdir(dirPath, { withFileTypes: true });
139	
140	      for (const entry of entries) {
141	        const fullPath = path.join(dirPath, entry.name);
142	
143	        if (this.shouldScanDirectory(entry, depth)) {
144	          await this.scanDirectory(fullPath, result, depth + 1);
145	        } else if (this.shouldCountCertificate(entry, depth)) {
146	          result.certificateCount++;
147	        }
148	      }
149	    } catch (error) {
150	      if (error instanceof Error) {
151	        const errorInfo: DetectionError = {
152	          error: error.message,
153	          code: (error as NodeJS.ErrnoException).code,
154	        };
155	        result.errors.push(errorInfo);
156	      }
157	    }
158	  }
159	
160	  private shouldScanDirectory(entry: Dirent, depth: number): boolean {
161	    return entry.isDirectory() && !entry.isSymbolicLink() && depth === 0 && this.isValidRegistryDirectory(entry.name);
162	  }
163	
164	  private shouldCountCertificate(entry: Dirent, depth: number): boolean {
165	    const isValidFile = entry.isFile() || (entry.isSymbolicLink() && this.config.followSymlinks);
166	    return isValidFile && depth >= 1 && this.isCertificateFile(entry.name);
167	  }
168	
169	  private isCertificateFile(filename: string): boolean {
170	    const ext = path.extname(filename).toLowerCase();
171	
172	    if (this.config.excludedExtensions.includes(ext)) {
173	      return false;
174	    }
175	
176	    return this.config.validCertExtensions.includes(ext);
177	  }
178	
179	  private isValidRegistryDirectory(directoryName: string): boolean {
180	    // According to containers-certs.d(5), directory names should follow hostname:port format
181	    // Examples: registry.example.com:5000, localhost:5000, example.com
182	
183	    // Allow hostname without port (default port assumed)
184	    const hostnamePattern = /^[a-zA-Z0-9]([a-zA-Z0-9.-]*[a-zA-Z0-9])?$/;
185	    const hostnamePortPattern = /^[a-zA-Z0-9]([a-zA-Z0-9.-]*[a-zA-Z0-9])?:\d+$/;
186	
187	    return hostnamePattern.test(directoryName) || hostnamePortPattern.test(directoryName);
188	  }
189	
190	  protected async getDirectoriesToScan(): Promise<string[]> {
191	    const directories: string[] = [...this.config.certDirectories.system];
192	
193	    const homeDir = os.homedir();
194	    const userDirs = this.config.certDirectories.user.map(dir => dir.replace('$HOME', homeDir));
195	    directories.push(...userDirs);
196	
197	    const existingDirs: string[] = [];
198	    for (const dir of directories) {
199	      try {
200	        await fs.access(dir, fs.constants.R_OK);
201	        existingDirs.push(dir);
202	      } catch (error) {
203	        const nodeError = error as NodeJS.ErrnoException;
204	        if (nodeError.code && nodeError.code !== 'ENOENT') {
205	          console.debug(`Certificate directory not accessible: ${dir} (${nodeError.code})`);
206	        }
207	      }
208	    }
209	
210	    return existingDirs;
211	  }
