31	/**
32	 * Provides access to the certificates of the underlying platform.
33	 * It supports Linux, Windows and MacOS.
34	 */
35	@injectable()
36	export class Certificates {
37	  private allCertificates: string[] = [];
38	
39	  /**
40	   * Setup all certificates globally depending on the platform.
41	   */
42	  async init(): Promise<void> {
43	    this.allCertificates = await this.retrieveCertificates();
44	
45	    // initialize the certificates globally
46	    https.globalAgent.options.ca = this.allCertificates;
47	  }
48	
49	  getAllCertificates(): string[] {
50	    return this.allCertificates;
51	  }
52	
53	  async retrieveCertificates(): Promise<string[]> {
54	    if (isMac()) {
55	      return this.retrieveMacOSCertificates();
56	    } else if (isWindows()) {
57	      return this.retrieveWindowsCertificates();
58	    } else if (isLinux()) {
59	      return this.retrieveLinuxCertificates();
60	    }
61	
62	    // else return default root certificates
63	    return [...tls.rootCertificates];
64	  }
65	
66	  public extractCertificates(content: string): string[] {
67	    // need to create an array of text from the content starting by '-----BEGIN CERTIFICATE-----'
68	    // use a regexp
69	    return content.split(/(?=-----BEGIN CERTIFICATE-----)/g).filter(c => c.trim().length > 0);
70	  }
71	
72	  async retrieveMacOSCertificates(): Promise<string[]> {
73	    const rootCertificates = await this.getMacOSCertificates(
74	      '/System/Library/Keychains/SystemRootCertificates.keychain',
75	    );
76	    const userCertificates = await this.getMacOSCertificates();
77	    return rootCertificates.concat(userCertificates);
78	  }
