80	  // get the certificates from the Windows certificate store
81	  async retrieveWindowsCertificates(): Promise<string[]> {
82	    // delegate to the win-ca module
83	    const winCaRetrieval = new Promise<string[]>(resolve => {
84	      const CAs: string[] = [...tls.rootCertificates];
85	
86	      if (import.meta.env.PROD) {
87	        const rootExePath = path.join(process.resourcesPath, 'win-ca', 'roots.exe');
88	        wincaAPI.exe(rootExePath);
89	      } else {
90	        wincaAPI.exe(require.resolve('win-ca/lib/roots.exe'));
91	      }
92	
93	      wincaAPI({
94	        format: wincaAPI.der2.pem,
95	        inject: false,
96	        store: ['root', 'ca'],
97	        ondata: (ca: string) => {
98	          CAs.push(ca);
99	        },
100	        onend: () => {
101	          resolve(CAs);
102	        },
103	      });
104	    });
105	
106	    try {
107	      const result = await winCaRetrieval;
108	      // also do the patch on tls.createSecureContext()
109	      wincaAPI.inject('+');
110	      return result;
111	    } catch (error) {
112	      console.error('Error while retrieving Windows certificates', error);
